### Opção 2: Script do Console (Se o bookmarklet não funcionar)

1. Abra [home.nest.com](https://home.nest.com) em uma **janela anônima** e faça login
2. Pressione `F12` → Clique na aba **Console**
3. Cole e execute este script:

```javascript
(async function() {
  try {
    if (!window.location.hostname.includes('nest.com')) {
      alert('❌ Site errado! Este script deve ser executado em home.nest.com');
      return;
    }
    const entries = performance.getEntriesByType('resource');
    const issueTokenEntry = entries.find(e => e.name.includes('issueToken'));
    if (!issueTokenEntry) {
      alert('❌ Nenhum issueToken encontrado. Por favor:\n1. Atualize a página (F5)\n2. Aguarde até que esteja totalmente carregada\n3. Execute este script novamente');
      return;
    }
    const issueToken = issueTokenEntry.name;
    const cookies = document.cookie;
    if (!issueToken.startsWith('https://accounts.google.com/o/oauth2/iframerpc')) {
      alert('❌ URL de issue token inválida');
      return;
    }
    if (!issueToken.includes('action=issueToken')) {
      alert('❌ URL de issue token inválida (action=issueToken ausente)');
      return;
    }
    if (!cookies || cookies.length < 100) {
      alert('❌ Cookies não encontrados ou incompletos. Certifique-se de estar conectado.');
      return;
    }
    const requiredCookies = ['HSID=', 'SSID=', 'APISID=', 'SAPISID='];
    const missingCookies = requiredCookies.filter(c => !cookies.includes(c));
    if (missingCookies.length > 0) {
      alert('⚠️ Aviso: Cookies ausentes: ' + missingCookies.join(', ').replace(/=/g, ''));
    }
    console.log('\n========================================');
    console.log('✅ CREDENCIAIS EXTRAÍDAS COM SUCESSO!');
    console.log('========================================\n');
    console.log('URL do Issue Token:\n' + issueToken + '\n');
    console.log('Cookies:\n' + cookies + '\n');
    console.log('========================================\n');
    const text = `URL do Issue Token:\n${issueToken}\n\nCookies:\n${cookies}`;
    try {
      await navigator.clipboard.writeText(text);
      alert('✅ Credenciais copiadas para a área de transferência!\n\nCole-as no Home Assistant abaixo.');
    } catch (e) {
      alert('✅ Credenciais extraídas!\n\nCopie-as da saída do console acima.');
    }
  } catch (error) {
    console.error('Erro:', error);
    alert('❌ Ocorreu um erro: ' + error.message);
  }
})();
```

4. Copie as credenciais e cole-as abaixo

